import java.util.*;

public class CF884F {
    static final int A = 26, INF = Integer.MAX_VALUE / 4;
    int n, N, S, T;
    ArrayList<ArrayList<Edge>> g;
    int[] pot;
    boolean[] vis;

    static class Edge {
        int to, rev, cap, cost;
        Edge(int to, int rev, int cap, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    void addEdge(int v, int to, int cap, int cost) {
        Edge a = new Edge(to, g.get(to).size(), cap, cost);
        Edge b = new Edge(v, g.get(v).size(), 0, -cost);
        g.get(v).add(a);
        g.get(to).add(b);
    }

    int dfs(int v, int f) {
        if (v == T) return f;
        vis[v] = true;
        for (Edge e : g.get(v)) {
            if (e.cap > 0 && !vis[e.to] && e.cost + pot[v] - pot[e.to] == 0) {
                int ret = dfs(e.to, Math.min(f, e.cap));
                if (ret > 0) {
                    e.cap -= ret;
                    g.get(e.to).get(e.rev).cap += ret;
                    vis[v] = false;
                    return ret;
                }
            }
        }
        vis[v] = false;
        return 0;
    }

    int minCostFlow(int s, int t) {
        S = s;
        T = t;
        pot = new int[N];
        Arrays.fill(pot, INF);
        pot[s] = 0;

        for (int it = 0; it < N - 1; it++) {
            boolean upd = false;
            for (int v = 0; v < N; v++) {
                if (pot[v] == INF) continue;
                for (Edge e : g.get(v)) {
                    if (e.cap > 0 && pot[e.to] > pot[v] + e.cost) {
                        pot[e.to] = pot[v] + e.cost;
                        upd = true;
                    }
                }
            }
            if (!upd) break;
        }

        int total = 0;
        while (true) {
            int[] dist = new int[N];
            Arrays.fill(dist, INF);
            dist[s] = 0;

            PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
            pq.add(new long[] {0, s});

            while (!pq.isEmpty()) {
                long[] cur = pq.poll();
                int v = (int) cur[1];
                int d = (int) cur[0];
                if (d != dist[v]) continue;
                for (Edge e : g.get(v)) {
                    if (e.cap <= 0) continue;
                    int nd = d + e.cost + pot[v] - pot[e.to];
                    if (dist[e.to] > nd) {
                        dist[e.to] = nd;
                        pq.add(new long[] {nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;

            for (int v = 0; v < N; v++)
                if (dist[v] < INF) pot[v] += dist[v];

            vis = new boolean[N];
            while (true) {
                int f = dfs(s, Integer.MAX_VALUE);
                if (f == 0) break;
                total += f * (pot[t] - pot[s]);
            }
        }
        return total;
    }

    void run() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt() / 2;
        N = 1 + n + A + 1;
        g = new ArrayList<>();
        for (int i = 0; i < N; i++) g.add(new ArrayList<>());

        byte[] s = sc.next().getBytes();
        int[] b = new int[n * 2];
        for (int i = 0; i < n * 2; i++) b[i] = sc.nextInt();

        int source = 0, sink = N - 1;
        for (int i = 0; i < n; i++) addEdge(source, 1 + i, 2, 0);

        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int ai = s[i] - 'a';
            int aj = s[j] - 'a';
            for (int a = 0; a < A; a++) {
                int val;
                if (a == ai && a == aj) val = Math.max(b[i], b[j]);
                else if (a == ai) val = b[i];
                else if (a == aj) val = b[j];
                else val = 0;
                addEdge(1 + i, 1 + n + a, 1, -val);
            }
        }

        int[] cnt = new int[A];
        for (int i = 0; i < n * 2; i++) cnt[s[i] - 'a']++;
        for (int a = 0; a < A; a++) addEdge(1 + n + a, sink, cnt[a], 0);

        System.out.println(-minCostFlow(source, sink));
    }

    public static void main(String[] args) {
        new CF884F().run();
    }
}
